const input = $input.first().json.body || $input.first().json;
const bills = Array.isArray(input.bills) ? input.bills : [];
const records = bills.map((b, i) => {
  const amount = Number(b.amount || 0);
  const cap = b.maxAmountCap == null ? null : Number(b.maxAmountCap);
  const priorAmount = b.priorAmount == null ? null : Number(b.priorAmount);
  const due = b.dueDate ? new Date(b.dueDate) : null;
  const hours = Number(b.preDebitNotificationHours || 0);
  return { ref: b.referenceNumber || `bill-${i + 1}`, category: b.category || 'unknown', amount, priorAmount, amountChangePercent: priorAmount && priorAmount !== 0 ? Math.round(((amount - priorAmount) / priorAmount) * 10000) / 100 : null, dueDate: b.dueDate || null, mandateStatus: b.mandateStatus || 'unknown', cap, exceedsCap: cap !== null && amount > cap, notificationHours: hours, notificationConfigured: hours > 0, gracePeriodDays: Number(b.gracePeriodDays || 0), dueDateValid: !due || !Number.isNaN(due.getTime()) };
});
const prompt = `Review these bill and recurring-payment metadata records for exceptions: amount-cap exceedance, missing notification configuration, invalid/missing dates, inactive mandates, and material changes from prior amounts. Give flags and suggested verification steps only. Never initiate, approve, cancel, or change a payment or mandate. Do not request account numbers, credentials, UPI PINs, or OTPs. Return JSON keys exceptions (array), checks (array), needsHumanReview (boolean).
${JSON.stringify(records)}`;
return [{ json: { records, prompt } }];

const response = $input.first().json;
const records = $('Prepare Bill Exceptions').first().json.records;
let review;
try { review = JSON.parse(response.candidates[0].content.parts[0].text); } catch { review = { exceptions: [], checks: ['AI response could not be parsed; inspect the bill metadata manually.'], needsHumanReview: true }; }
return [{ json: { status: 'review_ready', records, aiReview: review, requiresHumanApproval: true, paymentActionsTaken: [] } }];
